export type RefactorCandidateKind =
  | "split-module"
  | "extract-helper"
  | "deduplicate-function"
  | "externalize-literal"
  | "externalize-policy";

export interface RefactorCandidate {
  kind: RefactorCandidateKind;
  path: string;
  subject: string;
  score: number;
  threshold: number;
  confidence: "high" | "medium";
  reason: string;
}

export const REFACTOR_FEEDBACK_LIMIT = 20;

function stableHash(value: string): string {
  return `sha256:${createHash("sha256").update(value).digest("hex")}`;

export function analyzeRefactorCandidates(
  files: Array<{ path: string; content: string }>,
  policy: RefactorCandidatePolicy = DEFAULT_REFACTOR_CANDIDATE_POLICY,
): RefactorCandidate[] {
  const candidates: RefactorCandidate[] = [];
  const bodyIndex = new Map<string, Array<{ path: string; name: string; lines: number }>>();
  const allPaths = new Set(files.map((file) => file.path));

  for (const file of files) {
    const lines = file.content.split(/\r?\n/);
    const nonBlankLineCount = lines.filter((line) => line.trim()).length;
    const stripped = stripTsComments(file.content);
    const exportCount = (stripped.match(/\bexport\s+/g) ?? []).length;
    const functions = collectFunctionBodies(file.content);
    const declarativeCatalog = isDeclarativeCatalogModule(file, functions.length);
    if (
      nonBlankLineCount >= policy.thresholds.splitModuleLines ||
      (exportCount >= policy.thresholds.splitModuleExports && !isExportCatalogExempt(file))
    ) {
      const isLineTriggered = nonBlankLineCount >= policy.thresholds.splitModuleLines;
      const score = isLineTriggered ? nonBlankLineCount : exportCount;
      const threshold = isLineTriggered
        ? policy.thresholds.splitModuleLines
        : policy.thresholds.splitModuleExports;
      candidates.push({
        kind: "split-module",
        path: file.path,
        subject: file.path,
        score,
        threshold,
        confidence: splitModuleConfidence({
          score,
          threshold,
          functions,
          declarativeCatalog,
          policy,
        }),
        reason: `module has ${nonBlankLineCount} nonblank line(s) and ${exportCount} export(s)`,
      });

for (const fn of functions) {
  if (fn.lines >= policy.thresholds.extractHelperLines) {
    candidates.push({
      kind: "extract-helper",
      path: file.path,
      subject: `${file.path}#${fn.name}`,
      score: fn.lines,
      threshold: policy.thresholds.extractHelperLines,
      confidence: candidateConfidence({
        kind: "extract-helper",
        score: fn.lines,
        threshold: policy.thresholds.extractHelperLines,
        policy,
      }),
      reason: `function ${fn.name} has ${fn.lines} nonblank line(s)`,
    });
  }
  if (fn.lines >= policy.thresholds.dedupeFunctionMinLines) {
    const key = normalizedBody(fn.body);
    if (key.length > 0) {
      const bucket = bodyIndex.get(key) ?? [];
      bucket.push({ path: file.path, name: fn.name, lines: fn.lines });
      bodyIndex.set(key, bucket);
    }
  }
}

const literalCounts = new Map<string, number>();
for (const literal of collectStringLiterals(
  file.content,
  policy.thresholds.externalizeLiteralMinLength,
)) {
  literalCounts.set(literal, (literalCounts.get(literal) ?? 0) + 1);
}
for (const [literal, count] of literalCounts) {
  if (count >= policy.thresholds.externalizeLiteralMinRepeats) {
    candidates.push({
      kind: "externalize-literal",
      path: file.path,
      subject: `${file.path}#literal:${stableHash(literal).slice(0, 19)}`,
      score: count,
      threshold: policy.thresholds.externalizeLiteralMinRepeats,
      confidence: candidateConfidence({
        kind: "externalize-literal",
        score: count,
        threshold: policy.thresholds.externalizeLiteralMinRepeats,
        policy,
      }),
      reason: `literal appears ${count} time(s); consider a named constant or config boundary`,
    });
  }
}

candidates.push(...collectExternalizedPolicyCandidates({ ...file, allPaths, policy }));

  for (const matches of bodyIndex.values()) {
    const paths = new Set(matches.map((m) => `${m.path}#${m.name}`));
    if (paths.size < 2) continue;
    const sorted = [...matches].sort((a, b) =>
      `${a.path}#${a.name}`.localeCompare(`${b.path}#${b.name}`),
    );
    const subject = sorted.map((m) => `${m.path}#${m.name}`).join(",");
    candidates.push({
      kind: "deduplicate-function",
      path: sorted[0]?.path ?? "",
      subject,
      score: sorted.length,
      threshold: 2,
      confidence: candidateConfidence({
        kind: "deduplicate-function",
        score: sorted.length,
        threshold: 2,
        policy,
      }),
      reason: `duplicate function body appears in ${sorted.length} function(s): ${subject}`,
    });
  }

  return candidates.sort(
    (a, b) => a.kind.localeCompare(b.kind) || a.subject.localeCompare(b.subject),
  );
}

// @helix-repo-wide-guard
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";

type Family = {
  family: string;
  predecessor_plan_id: string;
  required_successor: string;
  expected_count: number;
};

type Binding = {
  signal_type: string;
  source_id: string;
  source_path: string;
  source_file_sha256: string;
  family: string;
};

const manifest = JSON.parse(
  readFileSync("docs/governance/feedback-refactor-disposition.json", "utf8"),
) as {
  schema_version: string;
  issue_id: number;
  disposition_plan_id: string;
  activation_phase: string;
  families: Family[];
  bindings: Binding[];
};

function digest(text: string): string {
  return createHash("sha256").update(text).digest("hex");
}

describe("PLAN-L3-32 refactor warning disposition", () => {
  it("pins twenty unique signals across the 9/6/5 successor partition", () => {
    expect(manifest.schema_version).toBe("feedback-refactor-disposition.v1");
    expect(manifest.issue_id).toBe(74);
    expect(manifest.bindings).toHaveLength(20);
    expect(new Set(manifest.bindings.map((row) => row.source_id)).size).toBe(20);

    const expectedCounts = new Map(
      manifest.families.map((row) => [row.family, row.expected_count]),
    );
    expect([...expectedCounts.values()].reduce((sum, count) => sum + count, 0)).toBe(20);
    for (const [family, expected] of expectedCounts) {
      expect(
        manifest.bindings.filter((row) => row.family === family),
        family,
      ).toHaveLength(expected);
    }
  });

it("matches every current source digest", () => {
  for (const row of manifest.bindings) {
    expect(digest(readFileSync(row.source_path, "utf8")), row.source_path).toBe(
      row.source_file_sha256,
    );
    expect(row.source_id.startsWith(`refactor-candidate:${row.signal_type.split(":")[1]}:`)).toBe(
      true,
    );
  }
});

it("requires additive successors instead of claiming predecessor completion", () => {
  expect(manifest.activation_phase).toBe("post_g3_refactor_queue");
  expect(manifest.families).toHaveLength(3);
  expect(manifest.families.every((row) => row.required_successor.includes("new additive"))).toBe(
    true,
  );
  expect(new Set(manifest.families.map((row) => row.predecessor_plan_id)).size).toBe(3);
  expect(new Set(manifest.families.map((row) => row.required_successor)).size).toBe(3);
  for (const family of manifest.families) {
    expect(
      readFileSync(`docs/plans/${family.predecessor_plan_id}.md`, "utf8"),
      family.predecessor_plan_id,
    ).toContain("status: confirmed");
  }
});

it("keeps L3 disposition closure separate from downstream implementation and freeze", () => {
  const plan = readFileSync("docs/plans/PLAN-L3-32-feedback-refactor-disposition.md", "utf8");
  expect(plan).toContain("status: confirmed");
  expect(plan).toContain("de7d019c7e1d954e4613e203ec89de569a7075f0");
  expect(plan).toContain("pull/105#issuecomment-5056917506");
  expect(plan).toContain("rows=48359");
  expect(plan).toContain("L7 refactor PLAN起票");
  expect(plan).toContain("behavior fence");
  expect(plan).toContain("G1/G3 freeze済みを意味しない");
  expect(plan).toContain("refactor実施完了を主張しない");
  expect(plan).toContain("requirements G1/G3 freeze");
});
